    "engineeringData": {
      "blockDesign": "Longitudinal 3.0L 72-degree V6. Constructed with an aluminum block featuring cast iron cylinder liners. The unusual 72-degree V-angle creates a highly compact engine that fits easily between the shock towers, but introduces inherent secondary vibrations, necessitating a dedicated, counter-rotating balance shaft housed deep within the block.",
      "crankshaft": "Forged, micro-alloy steel crankshaft supported by 4 massively reinforced main bearings.",
      "pistonSpeed": "14.3 m/s @ 4000 RPM. Lightweight aluminum pistons featuring specialized internal oil cooling galleries to survive the extreme heat of direct diesel combustion.",
      "alternator": "180A Bosch unit featuring smart-charge technology (BlueEFFICIENCY) that decouples the alternator under acceleration to reduce parasitic drag.",
      "rotatingAssembly": { "pistonConstruction": "Cast aluminum with internal cooling channels.", "wristPinDiameter": "30 mm.", "connectingRodLength": "155 mm.", "rodBoltSize": "M10", "crankMainJournal": "70.0 mm.", "crankRodJournal": "56.0 mm.", "rodRatio": "1.80" },
      "cylinderHead": { "combustionChamberVol": "DOHC, 4-valve per cylinder.", "intakePortFlow": "Dual-port swirl-optimized design. One port provides straight flow, the other forces air into a vortex using electronic tumble flaps.", "valveSizes": "Intake: 28.5 mm / Exhaust: 25.5 mm.", "valveStemDiameter": "6.0 mm", "camshaftDuration": "Optimized strictly for massive low-RPM diesel torque.", "lifterType": "Hydraulic bucket tappets.", "specialFeature": "Piezoelectric injectors mounted directly vertical over the piston bowl for perfect fuel atomization." },
      "oilAndCooling": { "oilSquirters": "Yes, high-flow jets positioned under the pistons.", "oilPumpType": "Chain-driven variable volume gear pump.", "thermostatOpening": "92°C.", "oilCooler": "Integrated oil-to-water heat exchanger buried deep in the V-valley, surrounded by intense exhaust heat." },
      "fuelSystem": { "systemType": "Bosch Common Rail Direct Injection (CDI).", "maxPressure": "1600 Bar.", "injectors": "Piezoelectric." },
      "tuningLimits": { "maxSafeTorqueStock": "650 Nm", "maxSafePowerStock": "320 hp", "maxSafeRPM": "4500 RPM", "weakestLink": "The 7G-Tronic transmission clutches and the DPF backpressure are the limiting factors; pushing beyond 650 Nm will cause transmission slip and DPF blockage." },
      "electrical": { "coils": "N/A. Advanced Electronic Glow Plug Control.", "ecu": "Bosch EDC17 with BlueEFFICIENCY mapping." }
    },
