        engineeringData: { 
            blockDesign: "Longitudinal 5.5L 90-degree V8. High-pressure die-cast aluminum block. Hand-assembled under the 'One Man, One Engine' philosophy. Features Silitec (Alusil) cylinder liners. While highly thermally efficient, this silicon-aluminum matrix is incredibly intolerant to poor lubrication or fuel wash, making it highly susceptible to cylinder scoring.", crankshaft: "Forged steel, 5 main bearings. Massively over-engineered.", pistonSpeed: "16.1 m/s @ 6000 RPM.", alternator: "180A Bosch with smart recuperation.", rotatingAssembly: { pistonConstruction: "Cast aluminum with specialized bowl for direct injection tumbling.", wristPinDiameter: "24 mm.", connectingRodLength: "150 mm.", rodBoltSize: "M10.", crankMainJournal: "68.0 mm.", crankRodJournal: "52.0 mm.", rodRatio: "1.74." }, cylinderHead: { combustionChamberVol: "DOHC, 4-valve per cylinder (32 valves total).", intakePortFlow: "Straight, high-velocity intake ports for Direct Injection.", valveSizes: "Intake: 36.0 mm / Exhaust: 31.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Aggressive AMG profile.", lifterType: "Hydraulic roller finger followers.", specialFeature: "BlueDIRECT multi-spark ignition fires up to four times per millisecond." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-flow piston cooling jets.", oilPumpType: "Two-stage variable displacement vane pump.", thermostatOpening: "Electronically mapped (90-105°C).", oilCooler: "Integrated high-capacity heat exchanger." }, fuelSystem: { systemType: "Bosch BlueDIRECT High-Pressure Direct Injection.", maxPressure: "200 Bar (Fuel Rail).", injectors: "8x Piezoelectric injectors." }, tuningLimits: { maxSafeTorqueStock: "950 Nm", maxSafePowerStock: "750 hp", maxSafeRPM: "6800 RPM", weakestLink: "Stock intercooler thermal capacity and brittle plastic charge pipes." }, electrical: { coils: "8x multi-spark pencil coils.", ecu: "Bosch Motronic MED 17.7.3." } 
        },
