                { interval: "Before Winter", timeLimit: "1 year", task: "AdBlue / SCR System Check", details: "Keep AdBlue tank full to prevent the internal heater element from freezing and burning out, triggering the no-start countdown.", parts: ["AdBlue Fluid"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, 
                { interval: "Yearly", timeLimit: "1 year", task: "Front Suspension Check", details: "Check lower control arm bushings and AIRMATIC struts (if equipped) for wear caused by the heavy diesel block.", parts: ["Visual Check"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, 
                { interval: "100,000 km", timeLimit: "Unlimited", task: "Engine Mounts", details: "Inspect hydraulic engine mounts. Fluid leakage or excessive cabin vibration requires replacement.", parts: ["Lemförder Mounts"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "300 EUR" }
