        engineeringData: { 
            blockDesign: "Longitudinal 3.0L Inline-6. High-pressure die-cast aluminum block. Features NANOSLIDE cylinder coating. Because there is NO accessory belt drive (beltless engine), the engine is significantly shorter, allowing the timing chain to be placed at the rear of the block for optimal crash packaging.", crankshaft: "Forged steel, 7 main bearings. Inherently perfectly balanced inline-6 architecture requires no balancer shafts.", pistonSpeed: "15.0 m/s @ 6000 RPM.", alternator: "NO TRADITIONAL ALTERNATOR. The 48V ISG generates all electrical power and uses a DC/DC converter to charge the 12V system.", 
            rotatingAssembly: { pistonConstruction: "Cast aluminum with specialized bowl shape.", wristPinDiameter: "22 mm.", connectingRodLength: "150 mm.", rodBoltSize: "M9.", crankMainJournal: "64.0 mm.", crankRodJournal: "52.0 mm.", rodRatio: "1.66." }, 
            cylinderHead: { combustionChamberVol: "DOHC, 4-valve per cylinder (24 valves total).", intakePortFlow: "Variable valve lift via CAMTRONIC system.", valveSizes: "In: 34.0 mm / Ex: 29.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Electronically optimized for blending with the ISG and eZV compressor.", lifterType: "Hydraulic roller finger followers.", specialFeature: "CAMTRONIC and 350-bar direct injection." }, 
            oilAndCooling: { oilSquirters: "Yes, dedicated high-flow piston cooling jets.", oilPumpType: "Fully variable displacement vane pump.", thermostatOpening: "Electronically mapped by the ECU.", oilCooler: "Integrated coolant-to-oil heat exchanger." }, 
            fuelSystem: { systemType: "Bosch High-Pressure Direct Injection.", maxPressure: "350 Bar (Fuel Rail).", injectors: "6x Piezoelectric injectors." }, 
            tuningLimits: { maxSafeTorqueStock: "700 Nm", maxSafePowerStock: "500 hp", maxSafeRPM: "6500 RPM", weakestLink: "48V electrical system thermal limits and electric auxiliary compressor (eZV) integration." }, 
            electrical: { coils: "6x smart pencil coils.", ecu: "Bosch MG1. Fully integrated 48V hybrid management. Drives the 48V water pump and 48V A/C compressor." } 
        },
