                { interval: "150,000 km", timeLimit: "Unlimited", task: "HPFP Check", details: "Monitor high-pressure rail data via OBD. If oil smells heavily of fuel, replace HPFP immediately.", parts: ["Bosch HPFP"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "600 EUR" }
