            { partName: "Ignition Coil", category: "Ignition", oem: { brand: "MB Genuine", code: "A1769061400", approxPrice: "100 EUR" }, crossRef: { brand: "Bosch", code: "N/A", approxPrice: "55 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=A1769061400", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=A1769061400" }, note: "Replace all 8 if misfires occur." },
            { partName: "Air Filter", category: "Intake", oem: { brand: "MB Genuine", code: "A1760940100", approxPrice: "55 EUR" }, crossRef: { brand: "Mann Filter", code: "C 28 004", approxPrice: "28 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=A1760940100", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=C28004" }, note: "Crucial for Hot-V turbo efficiency." },
            { partName: "Engine Oil Filter", category: "Oil", oem: { brand: "MB Genuine", code: "A1761800009", approxPrice: "30 EUR" }, crossRef: { brand: "Mann Filter", code: "HU 7044 z", approxPrice: "15 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=A1761800009", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=HU7044Z" }, note: "High-capacity fleece filter element." }
