                { interval: "4 Years", timeLimit: "4 years", task: "A/C Service", details: "Recover and recharge R1234yf refrigerant. (A/C compressor relies on 48V system to cool battery).", parts: ["Refrigerant"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" }
