            { partName: "Engine Oil Filter", category: "Oil", oem: { brand: "MB Genuine", code: "A1761800009", approxPrice: "30 EUR" }, crossRef: { brand: "Mann Filter", code: "HU 7044 z", approxPrice: "15 EUR", source: "OEM Manufacturer", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=A1761800009", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=HU7044Z" }, note: "High-capacity fleece filter element." }
