            { partName: "Engine Mounts (Pair)", category: "Engine", oem: { brand: "MB Genuine", code: "A1662401117", approxPrice: "400 EUR" }, crossRef: { brand: "Lemförder", code: "39720 01", approxPrice: "190 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=A1662401117", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=3972001" }, note: "Collapse due to brutal 760 Nm launches." }
