        oemPlusUpgrades: [ 
            { name: "48V BMS Software Flash Update", description: "Having the dealer apply the latest patches for the 48V Battery Management System.", benefit: "CRITICAL. Prevents the infamous sudden 'bricking' of the 48V hybrid system and optimizes ISG cooling logic." },
            { name: "5,000-Mile / 8,000-km Oil Intervals", description: "Ignoring the factory long-drain intervals and changing the synthetic oil frequently.", benefit: "ABSOLUTELY MANDATORY. The only physical way to protect the incredibly difficult-to-access rear timing chain tensioners." },
            { name: "Intake Valve Walnut Blasting", description: "Removing the intake manifold to manually clean out thick carbon coking.", benefit: "CRITICAL PREVENTATIVE MAINTENANCE. Restores lost power, smooths out the idle, and prevents carbon chunks from destroying the cylinders." },
            { name: "High-Quality Dual-Voltage Trickle Charger", description: "Using an OEM or CTEK charger when parked for more than a week.", benefit: "Protects the delicate 12V and 48V battery balance, preventing deep-discharge faults that lock the ECU." }
        ],
