                { interval: "100,000 km", timeLimit: "Unlimited", task: "Electric Water Pump Inspection", details: "Monitor 48V electric water pump duty cycles. Preemptive replacement is highly recommended to avoid catastrophic AMG overheating.", parts: ["Pierburg Pump"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "350 EUR" }
